-- ============================================================================
-- NLS Premier League S02 — import des matchs (622) — JSON normalisé matchs-2026-10-14.json
-- Généré par scripts/plan-nls-basketball-games.mjs. TEXTE À RELIRE.
-- PROD : GO de BP seulement, jamais le mardi ni le mercredi avant 5 h.
-- ============================================================================
do $$
declare
  v_bp uuid; v_t timestamp := now() at time zone 'America/Toronto';
  n_lot int; n_base0 int; n_base1 int; n_meme int; n_depl int; n_nouv int; n_mod int; n_inch int;
  n_ins int; n_upd int; n_ret int; n_ret_nouv int; n_rev int; n_ops0 int; n_ops1 int; v_lot_no int; v_txt text;
  v_ins jsonb; v_mod jsonb; v_ret_nouv jsonb; v_ret_tous jsonb; v_ret_deja jsonb; v_div jsonb;
begin
  -- 0. fenêtre : jamais le mardi, ni le mercredi avant 5 h (Montréal)
  if coalesce(current_setting('nexus.essai_local', true), '') <> 'oui'
     and (extract(isodow from v_t) = 2 or (extract(isodow from v_t) = 3 and extract(hour from v_t) < 5)) then
    raise exception 'NEXUS: import NLS refusé — mardi, ou mercredi avant 5 h (%)', v_t; end if;
  select id into v_bp from public.users where email = 'bptds22@gmail.com';

  drop table if exists _nls_src; drop table if exists _nls_eq; drop table if exists _nls_res;
  drop table if exists _nls_base; drop table if exists _nls_lien;
  create temp table _nls_src (rang int primary key, libelle_div text not null, categorie text not null,
    division text not null, genre text not null, game_date date not null, game_time text,
    home_name text not null, visitor_name text not null, venue text, home_score int, visitor_score int,
    unique (categorie, division, genre, game_date, home_name, visitor_name)) on commit drop;
  select count(*) into n_lot from _nls_src;
  if n_lot <> 622 then raise exception 'NEXUS: lot de % match(s), attendu 622', n_lot; end if;

  -- 1. équipes : le JOURNAL de l'import des équipes, moins les retraits, et vivantes en base
  create temp table _nls_eq on commit drop as
    select (e->>'id')::uuid as id, e->>'libelle_pdf' as libelle, e->>'categorie' as categorie,
           e->>'division' as division, e->>'genre' as genre
      from public.admin_operations o, jsonb_array_elements(o.details->'equipes') e
     where o.operation = 'NLS_EQUIPES_CREEES'
       and (e->>'id')::uuid not in (select (x->>'id')::uuid from public.admin_operations r,
             jsonb_array_elements(r.details->'equipes') x where r.operation = 'NLS_EQUIPES_RETIREES')
       and (e->>'id')::uuid in (select id from public.teams where league = 'No Limits Showcases' and season = '2026-2027');
  if (select count(*) from _nls_eq) = 0 then raise exception 'NEXUS: aucune équipe NLS au journal — import impossible'; end if;
  if exists (select 1 from _nls_eq group by libelle, categorie, division, genre having count(*) > 1) then
    raise exception 'NEXUS: journal ambigu — deux équipes sous le même (nom, groupe)'; end if;

  create temp table _nls_res on commit drop as
    select s.*, th.id as home_team_id, tv.id as visitor_team_id from _nls_src s
      left join _nls_eq th on th.libelle = s.home_name and th.categorie = s.categorie and th.division = s.division and th.genre = s.genre
      left join _nls_eq tv on tv.libelle = s.visitor_name and tv.categorie = s.categorie and tv.division = s.division and tv.genre = s.genre;
  select string_agg(distinct format('« %s » (%s)', x.nom, x.div), ', ') into v_txt from (
    select home_name as nom, libelle_div as div from _nls_res where home_team_id is null
    union all select visitor_name, libelle_div from _nls_res where visitor_team_id is null) x;
  if v_txt is not null then raise exception 'NEXUS: équipe(s) inconnue(s) — RIEN n''est écrit : %', v_txt; end if;

  -- 2. la base : matchs NLS de la saison, dans les groupes que le lot couvre
  select count(*) into n_base0 from public.games where source_nom = 'NLS';
  create temp table _nls_base on commit drop as
    select g.id, g.category, g.division, g.sex_type, g.game_date, g.game_time, g.venue, g.home_score, g.visitor_score,
           g.is_played, g.collecte_le, g.home_name_raw, g.visitor_name_raw, g.home_team_id, g.visitor_team_id
      from public.games g
     where g.source_nom = 'NLS' and g.rseq_game_id is null and g.season = '2026-2027' and g.league_name = 'No Limits Showcases'
       and (g.category, g.division, g.sex_type) in (select distinct categorie, division, genre from _nls_src);
  if exists (select 1 from _nls_base group by category, division, sex_type, game_date, home_name_raw, visitor_name_raw having count(*) > 1) then
    raise exception 'NEXUS: la base porte déjà deux matchs NLS sous la même clé — à trancher par BP'; end if;

  -- 3. appariement : (a) même clé, (b) déplacement 1 pour 1 sur la paire NON orientée
  create temp table _nls_lien (rang int primary key, id uuid not null unique, mode text not null) on commit drop;
    on b.category = r.categorie and b.division = r.division and b.sex_type = r.genre
   and b.game_date = r.game_date and b.home_name_raw = r.home_name and b.visitor_name_raw = r.visitor_name;
      select categorie, division, genre, least(home_name, visitor_name) as a, greatest(home_name, visitor_name) as z,
             min(rang) as rang from _nls_res
       where rang not in (select rang from _nls_lien) group by 1, 2, 3, 4, 5 having count(*) = 1) s
    join (select category, division, sex_type, least(home_name_raw, visitor_name_raw) as a,
                 greatest(home_name_raw, visitor_name_raw) as z, (array_agg(id))[1] as id from _nls_base
       where id not in (select id from _nls_lien) group by 1, 2, 3, 4, 5 having count(*) = 1) b
      on b.category = s.categorie and b.division = s.division and b.sex_type = s.genre and b.a = s.a and b.z = s.z;

  -- un match apparié dont les ÉQUIPES ont changé (autres que les deux mêmes, échangées) : arrêt
  select string_agg(format('%s | %s | %s c. %s', r.libelle_div, r.game_date, r.home_name, r.visitor_name), ' ; ') into v_txt from _nls_lien l join _nls_res r using (rang) join _nls_base b on b.id = l.id
   where not ((b.home_team_id, b.visitor_team_id) = (r.home_team_id, r.visitor_team_id)
           or (b.home_team_id, b.visitor_team_id) = (r.visitor_team_id, r.home_team_id));
  if v_txt is not null then raise exception 'NEXUS: équipes changées sur un match connu — à trancher par BP : %', v_txt; end if;

  select count(*) filter (where mode = 'meme'), count(*) filter (where mode = 'deplace') into n_meme, n_depl from _nls_lien;
  select count(*) into n_nouv from _nls_res where rang not in (select rang from _nls_lien);
  select count(*) into n_mod from _nls_lien l join _nls_res r using (rang) join _nls_base b on b.id = l.id
   where (b.game_date, b.game_time, b.venue, b.home_score, b.visitor_score, b.is_played, b.home_name_raw)
         is distinct from (r.game_date, r.game_time, r.venue, r.home_score, r.visitor_score,
                           (r.home_score is not null and r.visitor_score is not null), r.home_name);
  n_inch := n_lot - n_nouv - n_mod;

  -- garde : l'état FINAL ne doit pas violer games_identite_civile (paire non orientée, sans sexe)
  select string_agg(format('%s %s %s : %s / %s', x.c, nullif(x.d, ''), x.j, x.a, x.z), ' ; ') into v_txt from (
    select c, d, j, a, z from (
      select g.category as c, g.division as d, g.game_date as j,
             least(g.home_name_raw, g.visitor_name_raw) as a, greatest(g.home_name_raw, g.visitor_name_raw) as z
        from public.games g where g.rseq_game_id is null and g.league_name = 'No Limits Showcases' and g.season = '2026-2027'
         and g.zone = '' and g.id not in (select id from _nls_lien)
      union all select r.categorie, r.division, r.game_date, least(r.home_name, r.visitor_name), greatest(r.home_name, r.visitor_name)
        from _nls_res r) f group by 1, 2, 3, 4, 5 having count(*) > 1) x;
  if v_txt is not null then raise exception 'NEXUS: même jour, mêmes équipes (games_identite_civile) — RIEN n''est écrit : %', v_txt; end if;

  -- 4. retirés : en base, dans un groupe couvert, sans correspondant. SIGNALÉS, jamais supprimés.
  select count(*) into n_ret from _nls_base where id not in (select id from _nls_lien);
  -- déjà signalés = la liste complète du dernier lot non défait
  select coalesce(o.details->'retires_tous', '[]') into v_ret_deja from public.admin_operations o
   where o.operation = 'NLS_MATCHS_IMPORT'
     and o.id::text not in (select r.details->>'lot' from public.admin_operations r where r.operation = 'NLS_MATCHS_ROLLBACK')
   order by (o.details->>'lot_no')::int desc limit 1;
  v_ret_deja := coalesce(v_ret_deja, '[]');
  -- revenus = déjà signalés que ce lot retrouve ; la liste complète garde les signalés hors des groupes du lot
  select count(*) into n_rev from jsonb_array_elements_text(v_ret_deja) x where x::uuid in (select id from _nls_lien);
  select coalesce(jsonb_agg(distinct x order by x), '[]') into v_ret_tous from (
    select x from jsonb_array_elements_text(v_ret_deja) x
     where x::uuid not in (select id from _nls_lien) and x::uuid not in (select id from _nls_base)
       and x::uuid in (select id from public.games)
    union select id::text from _nls_base where id not in (select id from _nls_lien)) t(x);
  select count(*), coalesce(jsonb_agg(jsonb_build_object('id', id, 'date', game_date, 'heure', game_time,
           'domicile', home_name_raw, 'visiteur', visitor_name_raw, 'categorie', category, 'division', division, 'genre', sex_type)
           order by game_date, home_name_raw), '[]')
    into n_ret_nouv, v_ret_nouv from _nls_base where id not in (select id from _nls_lien) and not (v_ret_deja ? id::text);

  -- 5. INSERT des nouveaux
  with ins as (
      home_team_id, visitor_team_id, home_name_raw, visitor_name_raw, home_score, visitor_score, is_played, venue,
      league_name, sport, division, category, zone, sex_type, source_nom, source_url, collecte_le)
    select '2026-2027', 'regular', null, r.game_date, r.game_time,
      r.home_team_id, r.visitor_team_id, r.home_name, r.visitor_name, r.home_score, r.visitor_score,
      (r.home_score is not null and r.visitor_score is not null), r.venue,
      'No Limits Showcases', 'Basketball', r.division, r.categorie, '', r.genre, 'NLS', 'https://basketball.exposureevents.com/277970/nls-premier-league-s02/schedule', '2026-10-14T11:14-04:00'::timestamptz
      from _nls_res r where r.rang not in (select rang from _nls_lien)
    returning id, category, division, sex_type, game_date, home_name_raw, visitor_name_raw)
  select count(*), coalesce(jsonb_agg(jsonb_build_object('id', ins.id, 'cle', format('%s | %s | %s c. %s', r.libelle_div, r.game_date, r.home_name, r.visitor_name)) order by r.rang), '[]')
    into n_ins, v_ins from ins join _nls_res r on r.categorie = ins.category and r.division = ins.division
     and r.genre = ins.sex_type and r.game_date = ins.game_date and r.home_name = ins.home_name_raw and r.visitor_name = ins.visitor_name_raw;

  -- 6. UPDATE limité, seulement si différent ; anciennes ET nouvelles valeurs au journal
  with upd as (
    update public.games g set game_date = r.game_date, game_time = r.game_time, venue = r.venue,
           home_score = r.home_score, visitor_score = r.visitor_score,
           is_played = (r.home_score is not null and r.visitor_score is not null),
           collecte_le = '2026-10-14T11:14-04:00'::timestamptz, updated_at = now(),
           -- inversion seulement : les deux mêmes équipes, côtés échangés (garde ci-dessus)
           home_team_id = r.home_team_id, visitor_team_id = r.visitor_team_id,
           home_name_raw = r.home_name, visitor_name_raw = r.visitor_name
      from _nls_lien l join _nls_res r using (rang) join _nls_base b on b.id = l.id
     where g.id = l.id
       and (b.game_date, b.game_time, b.venue, b.home_score, b.visitor_score, b.is_played, b.home_name_raw)
           is distinct from (r.game_date, r.game_time, r.venue, r.home_score, r.visitor_score,
                             (r.home_score is not null and r.visitor_score is not null), r.home_name)
    returning g.id, g.game_date, g.game_time, g.venue, g.home_score, g.visitor_score, g.is_played, g.collecte_le,
              g.home_team_id, g.visitor_team_id, g.home_name_raw, g.visitor_name_raw)
  select count(*), coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'cle', format('%s | %s | %s c. %s', r.libelle_div, r.game_date, r.home_name, r.visitor_name), 'mode', l.mode,
           'inverse', b.home_team_id <> u.home_team_id,
           'avant', jsonb_build_object('game_date', b.game_date, 'game_time', b.game_time, 'venue', b.venue,
                     'home_score', b.home_score, 'visitor_score', b.visitor_score, 'is_played', b.is_played, 'collecte_le', b.collecte_le,
                     'home_team_id', b.home_team_id, 'visitor_team_id', b.visitor_team_id,
                     'home_name_raw', b.home_name_raw, 'visitor_name_raw', b.visitor_name_raw),
           'apres', jsonb_build_object('game_date', u.game_date, 'game_time', u.game_time, 'venue', u.venue,
                     'home_score', u.home_score, 'visitor_score', u.visitor_score, 'is_played', u.is_played, 'collecte_le', u.collecte_le,
                     'home_team_id', u.home_team_id, 'visitor_team_id', u.visitor_team_id,
                     'home_name_raw', u.home_name_raw, 'visitor_name_raw', u.visitor_name_raw))
           order by r.rang), '[]')
    into n_upd, v_mod from upd u join _nls_lien l on l.id = u.id join _nls_res r using (rang) join _nls_base b on b.id = u.id;

  -- 7. gardes de nombre exact
  select count(*) into n_base1 from public.games where source_nom = 'NLS';
  if n_ins <> n_nouv or n_upd <> n_mod or n_base1 <> n_base0 + n_nouv then
    raise exception 'NEXUS: garde échouée — insérés %/% attendus, modifiés %/%, base NLS % -> % (attendu +%)',
      n_ins, n_nouv, n_upd, n_mod, n_base0, n_base1, n_nouv; end if;

  -- 8. journal : une ligne s'il y a du nouveau, du modifié, un retrait pas encore signalé ou un retour ; aucune sinon
  select jsonb_object_agg(libelle_div, n) into v_div from (select libelle_div, count(*) as n from _nls_src group by 1) d;
  select count(*) into n_ops0 from public.admin_operations;
  if n_ins + n_upd + n_ret_nouv + n_rev > 0 then
    select coalesce(max((details->>'lot_no')::int), 0) + 1 into v_lot_no from public.admin_operations where operation = 'NLS_MATCHS_IMPORT';
    values ('NLS_MATCHS_IMPORT', 'Import hebdomadaire des matchs NLS Premier League S02 (basketball 2026-2027)',
      jsonb_build_object('lot_no', v_lot_no, 'ligue', 'No Limits Showcases', 'saison', '2026-2027',
        'source', jsonb_build_object('nom', 'NLS', 'description', 'JSON normalisé matchs-2026-10-14.json', 'collecte_le', '2026-10-14T11:14-04:00'),
        'compte', jsonb_build_object('lot', n_lot, 'par_division', v_div, 'nouveaux', n_ins, 'modifies', n_upd,
                   'dont_deplaces', n_depl, 'inchanges', n_inch, 'retires', n_ret, 'retires_nouveaux', n_ret_nouv, 'retires_revenus', n_rev),
        'inseres', v_ins, 'modifies', v_mod, 'retires_nouveaux', v_ret_nouv, 'retires_tous', v_ret_tous),
      v_bp);
  end if;
  select count(*) into n_ops1 from public.admin_operations;
  if n_ops1 - n_ops0 <> (n_ins + n_upd + n_ret_nouv + n_rev > 0)::int then
    raise exception 'NEXUS: journal +%, attendu %', n_ops1 - n_ops0, (n_ins + n_upd + n_ret_nouv + n_rev > 0)::int; end if;

  for v_txt in select format('MATCH_RETIRE %s %s %s — %s %s, %s c. %s%s', category, nullif(division, ''), sex_type, game_date,
                            coalesce(game_time, '?'), home_name_raw, visitor_name_raw,
                            case when v_ret_deja ? id::text then ' [déjà signalé]' else '' end)
                from _nls_base where id not in (select id from _nls_lien) order by game_date, home_name_raw loop
    raise warning 'NEXUS: %', v_txt;
  end loop;
  raise notice 'NEXUS NLS matchs : lot %, nouveaux %, modifiés % (dont % déplacé(s)), inchangés %, inconnus 0, retirés % (dont % nouveau(x)), revenus % ; base NLS % -> % ; journal +%',
    n_lot, n_ins, n_upd, n_depl, n_inch, n_ret, n_ret_nouv, n_rev, n_base0, n_base1, n_ops1 - n_ops0;
end $$;
